## 使用示例

```js
import React, { useRef } from 'react';
import { XView, xNavigateTo, useXTaroOnShow, useXTaroOnReady, useXTaroOnHide, useXTaroOnDestroy, useXTaroAppOnLaunch } from '@ctrip/xtaro';
import BasePage from '@ctrip/xtaro/BasePage'; //小程序必须要继承BasePage
import './index.scss';

const Test = ()=>{
    // ------------  useXTaroOnShow ------------
    let useXTaroOnShowCallback1 = useRef((res) => {
      console.log("%c [xTaro] 111 useXTaroOnShow 触发（设置只触发一次） ----", "color:yellow;")
      console.log(res);
    }); // 当前页面展示只会触发一次  第二次进到这个页面回调不会触发
    useXTaroOnShow(useXTaroOnShowCallback1, {
      once: true
    });
    let useXTaroOnShowCallback2 = useRef((res)=>{
      console.log("%c [xTaro] 222 useXTaroOnShow 触发 ----", "color:yellow;")
      console.log(res);
    });
    useXTaroOnShow(useXTaroOnShowCallback2);

    // ------------  useXTaroOnReady ------------
    let useXTaroOnReadyCallback = useRef((res)=>{
      console.log("%c [xTaro] useXTaroOnReady 触发 ----", "color:yellow;")
      console.log(res);
    });
    useXTaroOnReady(useXTaroOnReadyCallback);

    // ------------  useXTaroOnHide ------------  
    let useXTaroOnHideCallback = useRef((res)=>{
      console.log("%c [xTaro] useXTaroOnHide 触发 ----", "color:yellow;")
      console.log(res);
    });
    useXTaroOnHide(useXTaroOnHideCallback)

    // ------------  useXTaroOnDestroy ------------  
    let useXTaroOnDestroyCallback = useRef((res)=>{
      console.log("%c [xTaro] useXTaroOnDestroy 触发 ----", "color:yellow;")
      console.log(res);
    });
    useXTaroOnDestroy(useXTaroOnDestroyCallback)

    // ------------  useXTaroAppOnLaunch ------------  
    let useXTaroAppOnLaunchCallback = useRef((res)=>{
      console.log("%c [xTaro] useXTaroAppOnLaunch 触发 ----", "color:yellow;")
      console.log(res);
    });
    useXTaroAppOnLaunch(useXTaroAppOnLaunchCallback)
    return (
      <XView>
        生命周期测试: 此为 Test 组件
      </XView>
    )
}

export default class Index extends BasePage {
    constructor(props) {
        super(props);
        console.log('Constructor.');
        // this.pageId = 111;
        this.state = {
          showTest: true
        }
    }
    getPageId = () => {
