    }

    // 跳转到 另一个 页面，用于触发 onHide 
    handleNav = () => {
      xNavigateTo({
        url: '/pages/test/test'
      });
    }
    hideTest = () => {
      this.setState({
        showTest: false
      })
    }
    render() {
        return (
            <XView className='home'>
